  christies:{vf:'S',src:[['The Art Newspaper, 17 Feb 2026','https://www.theartnewspaper.com/2026/02/17/sothebys-adjusts-buyers-premiums-fee-structures-securitisation'],['Grossman LLP, 14 May 2026: recent changes in buyer’s premiums','https://www.grossmanllp.com/strongspring-2026-auction-season-examining-recent-changes-in-buyers-premiumsstrong']]},
