function navHit(row,i,age,V){if(row.artists&&navArtistIn((navRule(i.from).exp.artists||[]),i.artist))return true;if(row.before&&+i.year<row.before)return true;if(row.age!=null&&!row.artists&&!row.before){const local=V/navFx(row.cur);return age>=row.age&&(row.value==null||local>=row.value);}return false;}
