  const f4=F(inter?'freight_inter':'freight_intra');line('freight',`Fine-art freight (${inter?'intercontinental, air':'within the continent'})`,f4.lo,f4.hi,f4.vf,f4.src,f4.note);
  const f5=F('insurance');line('insurance',`Transit insurance, nail to nail (${(f5.lo*100).toFixed(2)}–${(f5.hi*100).toFixed(2)}% of value)`,V*f5.lo,V*f5.hi,f5.vf,f5.src,f5.note);
