const NAV_CASES={moscow:{kind:'painting',value:3000000,year:1911,artist:'',living:false,mats:[],from:'uk',to:'us',mode:'auction',buyer:'ru',funds:'ru',owner:'person'},parisny:{kind:'painting',value:2500000,year:1890,from:'fr',to:'us',mode:'auction',buyer:'us',funds:'us',owner:'person',mats:[],living:false,artist:''},freeporthk:{kind:'painting',value:12000000,year:1965,from:'freeport',to:'hk',mode:'move',buyer:'hk',funds:'hk',owner:'company',mats:[],living:false,artist:''},loanny:{kind:'sculpture',value:4000000,year:1950,from:'ch',to:'us',mode:'loan',buyer:'ch',funds:'ch',owner:'person',mats:[],living:false,artist:''},madrid:{kind:'painting',value:1500000,year:1880,from:'es',to:'uk',mode:'private',buyer:'uk',funds:'uk',owner:'person',mats:[],living:false,artist:''},dubai:{kind:'sculpture',value:800000,year:2015,from:'uk',to:'ae',mode:'private',buyer:'ae',funds:'ae',owner:'person',mats:[],living:true,artist:''}};
